---@type IDataInfo
local IDataInfo = Plugins.Require("data_info", isClient and "client.info.CDataInfo" or "server.info.SDataInfo")
---@class PetDepotInfo : IDataInfo
local PetDepotInfo = class("PetDepotInfo", IDataInfo)
---@type PetDepotConfig
local PetDepotConfig = T(Global, "PetDepotConfig")
---@type CPetPkSender
local PetPkSender = T(Global, "PidPacketSender")

function PetDepotInfo:onCreate()
    ---key, defValue, toSelf, toOther, saveDB
    local cfgs = PetDepotConfig:getAllCfgs()
    for _, cfg in pairs(cfgs) do
        self:initKey(Define.PetDepotInfoKey.Unlock .. cfg.id, cfg.free and 1 or 0, true, false, true)
        self:initKey(Define.PetDepotInfoKey.Pets .. cfg.id, 0, true, false, false)
    end
end

---@param player SBasePlayer | CBasePlayer
function PetDepotInfo:initPlayer(player)
    self.player = player
end

function PetDepotInfo:getDepotPetCount(id)
    local pets = self.player.pet:getPets(Define.PetStatus.Depot)
    local count = 0
    for _, pet in pairs(pets) do
        if pet:getValue(Define.PetInfoKey.Position, true) == id then
            count = count + 1
        end
    end
    return count
end

function PetDepotInfo:onPlayerReady()
    local cfgs = PetDepotConfig:getAllCfgs()
    for _, cfg in pairs(cfgs) do
        self:setValue(Define.PetDepotInfoKey.Pets .. cfg.id, self:getDepotPetCount(cfg.id))
    end
end

function PetDepotInfo:isUnlock(id)
    return self:getValue(Define.PetDepotInfoKey.Unlock .. id) > 0
end

function PetDepotInfo:tryUnlockDepot(id)
    if self:isUnlock(id) then
        return
    end
    local cfg = PetDepotConfig:getCfgById(id)
    if not cfg then
        return
    end
    local cfgs = PetDepotConfig:getAllCfgs()
    local find
    for _, item in pairs(cfgs) do
        find = item
        if not self:isUnlock(item.id) then
            break
        end
    end
    if find ~= cfg then
        ---校验否是解锁当前最新的箱子，不可以跳过
        return
    end
    local price = cfg.price
    if isClient then
        local name = Lang:getString("gui.pet.depot.name") .. id
        local size = cfg.size .. "/" .. cfg.size
        CustomDialog.builder()
                    .setContentText(Lang:format("gui.pet.depot.unlock.tip", name, size))
                    .setCurrencyInfo(price[1], price[2])
                    .setRightClickListener(function()
            PayHelper.checkMoney(price[1], price[2], function(success)
                if success then
                    PetPkSender:tryUnlockPetDepot(id)
                end
            end)
        end)        .show()
    else
        PayHelper.payMoneySync(self.player, id, price[1], price[2], function()
            self:setValue(Define.PetDepotInfoKey.Unlock .. id, 1)
            self:setValue(Define.PetDepotInfoKey.Pets .. id, self:getDepotPetCount(id))
        end, nil, nil, "UnlockPetDepot")
    end
end

return PetDepotInfo